import{_ as n,C as o,c as r,o as s,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"General ledger","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/reporting/general-ledger.md","filePath":"master/finance/reporting/general-ledger.md","lastUpdated":1793074831000}'),l={name:"master/finance/reporting/general-ledger.md"};function d(c,e,h,g,p,u){const a=o("ImagePopup");return s(),r("div",null,[e[0]||(e[0]=t('<h1 id="general-ledger" tabindex="-1">General ledger <a class="header-anchor" href="#general-ledger" aria-label="Permalink to &quot;General ledger&quot;">​</a></h1><p>The general ledger lists every account that has a balance, with its opening balance, its movements and its closing balance. Use it when you need to know why an account has a certain amount, or to audit the books account by account.</p><blockquote><p><strong>In simple words:</strong> The general ledger is a drawer per account. Open a drawer to see every entry inside.</p></blockquote><p>It is in the Accounting app only: <code>Accounting → Reporting → General Ledger</code>.</p><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2>',5)),i(a,{src:"/images1/finance/general_ledger.png",alt:"General Ledger with Date Range Last Quarter (01/07/2026 - 30/09/2026), one account expanded to show its entry lines"}),e[1]||(e[1]=t('<ul><li><strong><em>Date Range:</em></strong> The period of the movements. Entries before the start date become the opening balance.</li><li><strong><em>Journals:</em></strong> Limit the report to chosen journals.</li></ul><p>Pick July 1 to July 31, 2026 to see the sample data. With the October default range the movements are zero, because nothing happened in October.</p><h2 id="how-to-read-it" tabindex="-1">How to read it <a class="header-anchor" href="#how-to-read-it" aria-label="Permalink to &quot;How to read it&quot;">​</a></h2><p>The columns are <strong>Account</strong>, <strong>Date</strong>, <strong>Communication</strong>, <strong>Partner</strong>, <strong>Debit</strong>, <strong>Credit</strong> and <strong>Balance</strong>.</p><ul><li>Each row is one account, for example <strong>121000 Account Receivable</strong>. Only accounts with a balance on the end date are listed.</li><li>On the account row, <strong>Debit</strong> and <strong>Credit</strong> are the movements in the range. <strong>Balance</strong> is the closing balance.</li><li>Click a row to open it. Click <strong>Expand All</strong> to open every account, and <strong>Collapse All</strong> to close them.</li><li>An opened account shows its opening balance first, then each entry line with the date, the label, the partner and the amounts.</li><li>The last row, <strong>Total General Ledger</strong>, sums the debit and credit.</li></ul><p>Example, balances as of end of October 2026:</p><table tabindex="0"><thead><tr><th>Account</th><th>Balance</th></tr></thead><tbody><tr><td>101403 Outstanding Receipts</td><td>891.25</td></tr><tr><td>101404 Outstanding Payments</td><td>-34,040.00</td></tr><tr><td>121000 Account Receivable</td><td>1,207.50</td></tr><tr><td>131000 Tax Paid</td><td>4,440.00</td></tr><tr><td>251000 Tax Received</td><td>-273.75</td></tr><tr><td>400000 Product Sales</td><td>-1,825.00</td></tr><tr><td>600000 Expenses</td><td>29,600.00</td></tr></tbody></table><p>For July 2026, <strong>Account Receivable</strong> has debits of 2,098.75 (both invoices) and a credit of 891.25 (the payment from Deco Addict). The balance is 1,207.50. <strong>Account Payable</strong> has a zero balance, so it is not listed.</p><p>A debit balance is positive. A credit balance is negative.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Click <strong>Export to Excel</strong> or <strong>Export to PDF</strong>. The file uses the same range and filters.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>Why are Debit and Credit zero but Balance is not?</strong> The range has no movements, but the account has an older balance. Move the range back.</p><p><strong>Where is the entry behind a line?</strong> Use <a href="./../accounting-entries/journal-items.html">Journal items</a> to search by account and open the entry.</p><p><strong>Why is an account missing?</strong> An account with a zero balance on the end date is hidden.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./trial-balance.html">Trial balance</a></li><li><a href="./../accounting-entries/journal-items.html">Journal items</a></li><li><a href="./">Reporting overview</a></li></ul>',17))])}const f=n(l,[["render",d]]);export{b as __pageData,f as default};
